function validate(input) {
  const [keysArr, valuesArr] = input;
  if (!Array.isArray(keysArr) || !Array.isArray(valuesArr)) return 'keysArr and valuesArr must both be JSON arrays.';
  if (keysArr.length !== valuesArr.length) return 'keysArr and valuesArr must have the same length.';
  if (JSON.stringify(keysArr).length > 500000 || JSON.stringify(valuesArr).length > 500000) return 'Each array is at most 5 * 10^5 characters of JSON.';
  if (keysArr.some((key) => String(key) === '__proto__')) return 'No key may convert to "__proto__".';
  return null;
}

