function adapt(input, solve, kit) {
  const [keysArr, valuesArr] = input;
  kit.trace(`createObject is called with ${keysArr.length} key${keysArr.length === 1 ? '' : 's'}`);
  const obj = solve(keysArr, valuesArr);
  if (obj === null || typeof obj !== 'object' || Array.isArray(obj) || obj instanceof Map) throw new Error('createObject must return a plain object, such as { "a": 1 }.');
  // Key order does not matter, so the answer lists the keys in sorted order.
  const answer = {};
  for (const key of Object.keys(obj).sort()) answer[key] = obj[key];
  kit.trace(`createObject returns ${JSON.stringify(answer)}`);
  return answer;
}

