function createObject(keysArr, valuesArr) {
  // Set from the last pair to the first, so the earliest pair of each key is written last and wins.
  const result = new Map();
  for (let i = keysArr.length - 1; i >= 0; i--) {
    result.set(String(keysArr[i]), valuesArr[i]);
  }
  return Object.fromEntries(result);
}

