function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const smallKeys = ['a', 'b', 'c', 'key', '1', '2', 'true', 'null', 'toString', 'constructor', '', 1, 2, 10, -1, true, false, null, [1, 2], '1,2', {}];
  const smallValues = [0, 1, -5, 42, '', 'x', 'value', null, true, false, [1], { k: 2 }];
  const letters = 'abcdef';
  const key = () => {
    if (size === 'small') return pick(smallKeys);
    const roll = rand();
    if (roll < 0.4) return Math.floor(rand() * 1500);
    if (roll < 0.5) return String(Math.floor(rand() * 1500));
    if (roll < 0.55) return pick([true, false, null]);
    return Array.from({ length: 1 + Math.floor(rand() * 4) }, () => pick(letters)).join('');
  };
  const value = () => (size === 'small' ? pick(smallValues) : rand() < 0.7 ? Math.floor(rand() * 2001) - 1000 : pick(smallValues));
  const length = size === 'small' ? Math.floor(rand() * 7) : 2000;
  const keysArr = Array.from({ length }, key);
  const valuesArr = Array.from({ length }, value);
  return [keysArr, valuesArr];
}
